package com.personal.assistant.module.stock.controller;import com.personal.assistant.common.response.ApiResponse;import com.personal.assistant.common.security.SecurityContextHelper;import com.personal.assistant.module.stock.dto.StockSectorFundFlowResponse;import com.personal.assistant.module.stock.mapper.StockSectorFundFlowMapper;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/stocks/fund-flow/sectors")public class StockSectorFundFlowController{private final StockSectorFundFlowMapper mapper;public StockSectorFundFlowController(StockSectorFundFlowMapper mapper){this.mapper=mapper;}@GetMapping public ApiResponse<StockSectorFundFlowResponse>sectors(){Long uid=SecurityContextHelper.currentUserId();return ApiResponse.success(new StockSectorFundFlowResponse("WATCH_INDUSTRY","EASTMONEY",mapper.latest(uid),mapper.sectors(uid)));}}
